#!/usr/bin/env python3
"""Writes Parse/EnvVar.lean: one equation per label for the variant `var` (EnvBase.lean).

`simp only [var]` on the 81-way string match costs ~40 s per use; the equations, proved once by
`rfl`, cost nothing at the use site.

Usage: var.py > Kraken/X64/Examples/Sbr/Parse/EnvVar.lean
"""

GROUPS = [
    ("5000", "_entry", "read_sbr_envelope L57c1 L57c9 L57ef L5834 L584c L5893 L58a4 L58c5 L58e6 L58f1"),
    ("100 * (10 - (s.regs.get64 .r9).toNat) + 99", "", "L58fd"),
    ("100 * (10 - fi s) + 99", "", "L590d L5930 L5a60 L5a95 L5be0 L5bf6 L5c26 L5c5e L5ca5 L5df4 "
     "L5e29 L5e2d L5e4b"),
    ("100 * (10 - fi s) + (60 - (s.regs.get64 .rsi).toNat)", "",
     "L5940 L595a L5998 L59d8 L5a0d L5a11 L5a38 L5cd0 L5ced L5cfd L5d35 L5d75 L5da6 L5daa L5dd7"),
    ("100 * (10 - fi s) + (60 - (s.regs.get64 .r9).toNat)", "",
     "L5ad0 L5ae4 L5b25 L5b61 L5b93 L5b97 L5bc7 L5e70 L5e8d L5eca L5f07 L5f3a L5f3e L5f6e"),
    ("100 * (10 - fi s)", "", "L5f90 L5fac L5fdd L5fe9 L6019"),
    ("0", "", "L603e L6044 L6048 L6063 L606a L6075 L60a6 done"),
]


def main():
  out = ["""import Kraken.X64.Examples.Sbr.Parse.EnvBase

/-!
# `read_sbr_envelope`: the variant at each label

Generated by `scripts/sbr/parse/env/var.py`.
-/

open Kraken Kraken.SysV Mem Kraken.X64.Parser

namespace Kraken.Examples.Sbr.Env
"""]
  for rhs, _, labs in GROUPS:
    for l in labs.split():
      full = l if l == "read_sbr_envelope" else f"read_sbr_envelope.{l}"
      name = "entry" if l == "read_sbr_envelope" else l
      out.append(f"""theorem var_{name} (s : MachineData) : var "{full}" s = {rhs} := rfl
""")
  out.append("end Kraken.Examples.Sbr.Env\n")
  print("\n".join(out))


main()
